import { normalizeElectorateName } from './electorate-names.js';
import {
  computeObservedSwing,
  computeSeatChance,
  DEFAULT_TAU,
  type SeatChance,
  type SeatPrior,
} from './seat-probability.js';
import type { ElectorateResult, VotingResults } from './types.js';

/**
 * Notional results: the previous cycle's votes rebuilt on this cycle's
 * boundaries. Generated by `scripts/build-notional-baseline.mjs`, which is the
 * only writer; see `docs/voting-place-data.md` for the method and its
 * deliberate limits.
 */
export type BaselineSeat = {
  kind: 'general' | 'maori';
  votes: number;
  places: number;
  partyShare: Record<string, number>;
  candidateShare: Record<string, number>;
  partyCandidateShare?: Record<string, number>;
  /**
   * Enrolled electors in the source cycle, recovered from that seat's own file
   * (`total_votes_cast ÷ percent_votes_cast`). `null` when the seat came from a
   * same-name carry-over rather than place geometry.
   */
  enrolment?: number | null;
  /**
   * This seat's special votes as a multiple of the source cycle's national
   * special-vote share (2023: Auckland Central 34.8% ÷ 21.0% = 1.66). Generated
   * from `data/special-votes-by-electorate.json`; absent when the prior had to
   * be apportioned from place geometry, because special votes are not cast at a
   * voting place and no polygon can find them.
   */
  specialRatio?: number | null;
};
export type NotionalBaseline = {
  sourceYear: number;
  targetYear: number;
  /**
   * Enrolled electors nationally in the source cycle, from `statistics.xml`.
   *
   * The seats' rolls are scaled to sum to this, because every elector sits in
   * exactly one seat. It is the check that catches a roll that only covers the
   * places the geometry could locate.
   */
  rollElectors?: number;
  method: string;
  tau: {
    transition: string;
    seats: number;
    meanMaxAbsDeviation: number;
    sdMaxAbsDeviation: number;
    maxAbsDeviation: number;
    /**
     * sd of each seat's departure from uniform national swing in the top-two
     * margin, in vote-share points. This is the number the model uses.
     */
    sdSwingDeviation?: number;
  } | null;
  coverage: {
    seats: number;
    placesLocated: number;
    placesSkipped: number;
    inSeatResults: number;
    outOfSeatResultsDropped?: number;
    seatsFromOwnPrior?: number;
    seatsApportioned?: number;
  };
  seats: Record<string, BaselineSeat>;
};

/**
 * Normalised seat name → baseline seat, built once per baseline object.
 *
 * A payload asks for the same seats several times over: `seatChanceFor` wants
 * both the prior and the enrolment of every seat, and `nationalSwingOf` walks
 * every seat's prior again. A linear scan that normalises each name on the way
 * is therefore seats² normalisations per render. The baseline is immutable and
 * lives for the life of the process, so a WeakMap keyed by the object is exact
 * and needs no invalidation.
 */
const seatsByName = new WeakMap<NotionalBaseline, Map<string, BaselineSeat>>();

function seatFor(
  baseline: NotionalBaseline | null,
  seatName: string | null | undefined
): BaselineSeat | null {
  if (!baseline || !seatName) return null;

  let index = seatsByName.get(baseline);
  if (!index) {
    index = new Map();
    for (const [name, seat] of Object.entries(baseline.seats)) {
      index.set(normalizeElectorateName(name), seat);
    }
    seatsByName.set(baseline, index);
  }

  return index.get(normalizeElectorateName(seatName)) ?? null;
}

/** The seat's prior result on the current boundaries, or null. */
export function priorForSeat(
  baseline: NotionalBaseline | null,
  seatName: string | null | undefined
): SeatPrior | null {
  const seat = seatFor(baseline, seatName);
  if (!seat) return null;
  return {
    partyShare: seat.partyShare,
    candidateShare: seat.candidateShare,
    partyCandidateShare: seat.partyCandidateShare,
  };
}

/** The seat's enrolled electors in the baseline cycle, when recorded. */
export function enrolmentForSeat(
  baseline: NotionalBaseline | null,
  seatName: string | null | undefined
): number | null {
  const enrolment = seatFor(baseline, seatName)?.enrolment;
  return enrolment && enrolment > 0 ? enrolment : null;
}

/**
 * How much of this seat's vote arrives as special votes, relative to the
 * cycle's national share.
 *
 * `null` when the baseline has no record — a seat built from place geometry, or
 * no baseline at all — and the model falls back to the flat national share,
 * which is what every seat used before this existed.
 */
export function specialRatioForSeat(
  baseline: NotionalBaseline | null,
  seatName: string | null | undefined
): number | null {
  const ratio = seatFor(baseline, seatName)?.specialRatio;
  return ratio && ratio > 0 ? ratio : null;
}

/**
 * Votes below which a back-solved enrolment is not worth trusting.
 *
 * The feed publishes `percent_votes_cast` to one decimal place, so 200 votes at
 * "0.4%" implies 50,000 enrolled against a seat's true 45,407. Once a couple of
 * thousand votes are in, that rounding is under a percent and the derived figure
 * is the better of the two — it is measured tonight, from this seat's own roll.
 */
const MIN_VOTES_FOR_DERIVED_ENROLMENT = 2000;

/** How far the two rolls must disagree before the live feed wins. */
const ENROLMENT_DISAGREEMENT = 0.1;

/**
 * The seat's roll, from the baseline or from tonight's own turnout.
 *
 * Enrolment is the denominator every progress number divides by, so getting it
 * wrong is not cosmetic: an understated roll understates the votes still to come
 * and overstates progress, which is the direction that manufactures confidence.
 * The baseline's figure is the source cycle's, and a seat's roll moves between
 * cycles — a few percent typically, and far more where the prior had to be
 * apportioned from place geometry rather than taken from the seat's own result.
 * So once enough votes are in to make the derivation precise, a live figure that
 * disagrees materially with the recorded one is evidence the baseline is stale,
 * and it wins.
 */
export function resolveEnrolment(input: {
  recorded?: number | null;
  votesCounted?: number;
  percentVotesCast?: number | null;
}): number | null {
  const recorded = input.recorded && input.recorded > 0 ? input.recorded : null;
  const votesCounted = input.votesCounted ?? 0;
  const turnout = input.percentVotesCast ?? 0;
  const derived =
    turnout > 0 && votesCounted > 0 ? votesCounted / turnout : null;

  if (!recorded) return derived;
  if (!derived) return recorded;
  if (votesCounted < MIN_VOTES_FOR_DERIVED_ENROLMENT) return recorded;
  const disagreement = Math.abs(derived / recorded - 1);
  return disagreement > ENROLMENT_DISAGREEMENT ? derived : recorded;
}

/**
 * How far seats typically stray from uniform national swing, as a standard
 * deviation of vote share. The fallback is used only when the baseline carries
 * no measurement.
 */
export function tauFor(baseline: NotionalBaseline | null): number {
  const measured =
    baseline?.tau?.sdSwingDeviation ?? baseline?.tau?.sdMaxAbsDeviation;
  return measured ? measured / 100 : DEFAULT_TAU;
}

/** Candidate votes folded up to the party that stood them. */
function candidateVotesByParty(
  votes: { candidate: string; party?: string; votes: number }[]
): VotingResults[] {
  const byParty = new Map<string, number>();
  for (const vote of votes) {
    if (!vote.party) continue;
    byParty.set(vote.party, (byParty.get(vote.party) ?? 0) + vote.votes);
  }
  return [...byParty].map(([candidate, count]) => ({
    candidate,
    votes: count,
  })) as VotingResults[];
}

/**
 * National swing measured across the seats counted so far.
 *
 * Measured from the night's own seats rather than a published table: it needs
 * no prior national result, and it corrects itself as the advance-heavy early
 * seats stop being the whole sample. The seat is decided on the candidate vote,
 * so the swing is measured there too.
 */
export function nationalSwingOf(
  baseline: NotionalBaseline | null,
  electorates: ElectorateResult[]
): Record<string, number> {
  if (!baseline) return {};
  return computeObservedSwing(
    electorates.map((result) => ({
      prior: priorForSeat(baseline, result.electorateName),
      parties: candidateVotesByParty(result.candidateVotes),
      votesCounted: result.votesCounted,
    }))
  );
}

/** The chance of winning the seat, given a baseline and a swing. */
export function seatChanceFor(
  result: ElectorateResult,
  baseline: NotionalBaseline | null,
  nationalSwing: Record<string, number>,
  electionYear: string | number | null | undefined
): SeatChance {
  return computeSeatChance({
    candidates: result.candidateVotes.map((c) => ({
      name: c.candidate,
      party: c.party,
      votes: c.votes,
    })),
    votesCounted: result.votesCounted,
    percentVotesCast: result.percentVotesCast,
    enrolment:
      resolveEnrolment({
        recorded: enrolmentForSeat(baseline, result.electorateName),
        votesCounted: result.votesCounted,
        percentVotesCast: result.percentVotesCast,
      }) ?? undefined,
    placesCounted: result.votePercentageCounted,
    electionYear: electionYear ? Number(electionYear) : null,
    prior: priorForSeat(baseline, result.electorateName),
    nationalSwing,
    tau: tauFor(baseline),
    specialRatio:
      specialRatioForSeat(baseline, result.electorateName) ?? undefined,
  });
}

/**
 * Build the per-seat chance lookup for one payload.
 *
 * The swing depends on every seat at once, so it is computed here rather than
 * per result. Returns `undefined` when no baseline is available, in which case
 * callers fall back to count-only language: a chance with no prior is a number
 * pretending to be informed.
 */
export function chanceLookupFor(
  baseline: NotionalBaseline | null,
  electorates: ElectorateResult[],
  electionYear: string | number | null | undefined
): ((result: ElectorateResult) => SeatChance) | undefined {
  if (!baseline) return undefined;
  const swing = nationalSwingOf(baseline, electorates);
  return (result) => seatChanceFor(result, baseline, swing, electionYear);
}
